// Determine next attack phase based on exercise progress
const exercise = $input.item.json;

if (exercise.status !== 'active') {
  return [];
}

const phases = [
  'reconnaissance',
  'vulnerability_scan',
  'exploitation',
  'post_exploitation',
  'lateral_movement',
  'data_exfiltration'
];

// Read exercise log to see what's been done
const currentPhase = exercise.current_phase || 0;
const nextPhase = phases[currentPhase] || 'reconnaissance';

return {
  json: {
    scenario: nextPhase,
    exercise_id: exercise.exercise_id,
    target: '10.0.30.0/24',
    intensity: 'medium'
  }
};
